"""Ordered algorithmic basis, including every exceptional index."""


def V_k_basis(k):
    if not 0 <= k <= N_int:
        raise ValueError("Expected 0 <= k <= N")
    if k == 0:
        return []
    u = ctx["x_0"]-ctx["x_star"]
    gradient = (1/params_sp["L"])*obj.grad(ctx[f"x_{k}"])
    if k == 1:
        return [u,gradient,ctx["x_1"]-ctx["x_star"]]
    if k == N_int:
        return [u,gradient,ctx[f"x_{k}"]-ctx["x_star"]]
    return [u,gradient,ctx[f"y_{k}"]-ctx["x_star"],ctx[f"y_{k+1}"]-ctx["x_star"]]


def V_k_basis_labels(k):
    if k == 0:
        return []
    if k == 1:
        return ["u",r"g_1/L",r"x_1-x_star"]
    if k == N_int:
        return ["u",f"g_{k}/L",f"x_{k}-x_star"]
    return ["u",f"g_{k}/L",f"y_{k}-x_star",f"y_{k+1}-x_star"]


basis_by_k = {k:V_k_basis(k) for k in range(N_int+1)}
basis_independence = {}
for k,vectors in basis_by_k.items():
    matrix = np.column_stack([pm.eval_vector(v).coords for v in vectors]).astype(float) if vectors else np.zeros((len(ctx.basis_vectors()),0))
    rank = int(np.linalg.matrix_rank(matrix,tol=1e-7)) if vectors else 0
    assert rank == len(vectors) == ranks[k], (k,rank,len(vectors),ranks[k])
    basis_independence[k] = dict(rank=rank,count=len(vectors),
        singular_values=np.linalg.svd(matrix,compute_uv=False).tolist())
    print(f"k={k}: rank {rank} basis {V_k_basis_labels(k)}")

